const canvas = { width:720, height:720, getContext: ()=>ctxStub };
globalThis.document = { getElementById: ()=>canvas };
globalThis.window = {};
globalThis.requestAnimationFrame = ()=>{};
eval(script);
const B = globalThis.window.__bench;
function inPoly(b, ang){
  for(let i=0;i<9;i++){
    const a1=ang+i*2*Math.PI/9, a2=ang+(i+1)*2*Math.PI/9;
    const ax=360+260*Math.cos(a1), ay=360+260*Math.sin(a1);
    const bx=360+260*Math.cos(a2), by=360+260*Math.sin(a2);
    let nx=-(by-ay), ny=(bx-ax); const L=Math.hypot(nx,ny); nx/=L; ny/=L;
    const mx=(ax+bx)/2,my=(ay+by)/2;
    if(nx*(360-mx)+ny*(360-my)<0){nx=-nx;ny=-ny;}
    const d=(b.x-ax)*nx+(b.y-ay)*ny;
    if(d < -1e-9) return d*-1;
  }
  return 0;
}
let escapes=0, overlaps=0, worstEsc=0, worstOvl=0;
// long stress run: 100s at 0.02s steps (5000 steps, also tests big dt handling)
for(let k=0;k<5000;k++){
  B.step(0.02);
  const st=B.getState();
  for(const b of st.balls){ const d=inPoly(b, st.poly.angle); if(d>1e-9){escapes++; worstEsc=Math.max(worstEsc,d);} }
  for(let i=0;i<13;i++)for(let j=i+1;j<13;j++){
    const a=st.balls[i],c=st.balls[j];
    const d=28-Math.hypot(a.x-c.x,a.y-c.y);
    if(d>1e-9){overlaps++; worstOvl=Math.max(worstOvl,d);}
  }
}
let allFinite=true, maxSp=0;
for(const b of B.getState().balls){
  if(![b.x,b.y,b.vx,b.vy].every(Number.isFinite)) allFinite=false;
  maxSp=Math.max(maxSp, Math.hypot(b.vx,b.vy));
}
console.log('t=',B.getState().t,'escapes',escapes,'(worst',worstEsc.toExponential(2)+')','overlaps',overlaps,'(worst',worstOvl.toExponential(2)+')');
console.log('all finite', allFinite, 'max speed', maxSp.toFixed(1));
// determinism check: same sequence twice
function runSteps(){
  // fresh eval for clean state
